from PyPDF2 import PdfReader

# Load the PDF file
def analyze_pdf(file_path):
    pdf_doc = PdfReader(file_path)
    pdf_fields = []
    if "/AcroForm" in pdf_doc.trailer["/Root"]:
        form = pdf_doc.trailer["/Root"]["/AcroForm"]
        if "/Fields" in form:
            for field in form["/Fields"]:
                field_object = field.get_object()
                field_name = field_object.get("/T")  # Field name
                field_value = field_object.get("/V")  # Field value
                pdf_fields.append((field_name, field_value))
    return pdf_fields

if __name__ == "__main__":
    pdf_path = "/home/ctfplayer/ctf_files/Tax_Ret_Form_Blank.pdf"
    fields = analyze_pdf(pdf_path)

    for field_name, field_value in fields:
        print(f"Field Name: {field_name}, Field Value: {field_value}")

import PyPDF2

def extract_text_from_pdf(file_path):
    try:
        # Open the PDF file
        with open(file_path, 'rb') as pdf_file:
            reader = PyPDF2.PdfReader(pdf_file)

            # Loop through all pages and extract text
            text = ""
            for page in reader.pages:
                text += page.extract_text() + "\n"

            return text
    except Exception as e:
        return str(e)

if __name__ == "__main__":
    pdf_path = "SPBlock_Email.pdf"
    extracted_text = extract_text_from_pdf(pdf_path)

    # Save the extracted text to a file
    with open("extracted_email_text.txt", "w") as output_file:
        output_file.write(extracted_text)

    print("Text extraction complete. Saved to extracted_email_text.txt.")

from PyPDF2 import PdfReader

def extract_stream_objects(filename):
    try:
        with open(filename, 'rb') as f:
            reader = PdfReader(f)
            for page_number, page in enumerate(reader.pages, start=1):
                print(f"Extracting streams from Page {page_number}:\n")
                print(repr(page))  # Raw text and object representation of the page
    except Exception as e:
        print("Error: " + str(e))

if __name__ == "__main__":
    extract_stream_objects("SPBlock_Email.pdf")

