#!/usr/bin/env python3
import zipfile

# List of possible passwords
password_list = ["2021", "Tax", "Nov_2021", "Tax_Ret", "finance", "SPBlock", "Blank_Form", "password"]

# Path to the ZIP file
zip_file_path = "/home/ctfplayer/ctf_files/Tax_Ret_Form_Nov_2021.zip"

# Function to try to open the zip file with a given password
def attempt_unzip(zip_file, password):
    try:
        with zipfile.ZipFile(zip_file, 'r') as zf:
            zf.extractall(pwd=password.encode('utf-8'))
            print(f"Success: Password is '{password}'")
            return True
    except (RuntimeError, zipfile.BadZipFile):
        return False

# Attempt to use each password in the list
for pwd in password_list:
    success = attempt_unzip(zip_file_path, pwd)
    if success:
        break
else:
    print("Failed to find the correct password.")

